<?php
use Moves\Services\{Finance,FinanceContext,RecurringFinance,SubscriptionBrands};
$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$service=new RecurringFinance((int)FinanceContext::currentId());
$requestedStatus=is_string($_GET['situacao']??null)?$_GET['situacao']:'active';
$status=in_array($requestedStatus,['active','paused','canceled'],true)?$requestedStatus:'active';
$rows=$service->listing($status);$counts=$service->counts();$finance=new Finance((int)FinanceContext::currentId());$accounts=$finance->accounts();
$expenseCategories=$finance->categories('expense');$incomeCategories=$finance->categories('income');
$base=\Moves\Services\AppUrl::section('recorrencias',\Moves\Services\OrganizationContext::current());
$frequencyLabels=['weekly'=>'Semanal','monthly'=>'Mensal','quarterly'=>'Trimestral','yearly'=>'Anual'];
$actionForm=static function(string $action,string $label,int $id)use($e,$csrf):string{return '<form method="post" action="/minha-conta/financeiro/recorrencia/'.$e($action).'"><input type="hidden" name="csrf_token" value="'.$e($csrf).'"><input type="hidden" name="id" value="'.$id.'"><button type="submit">'.$e($label).'</button></form>';};
?>
<?php $flash=$_SESSION['finance_flash']??null;unset($_SESSION['finance_flash']);if(is_array($flash)):?><p class="finance-flash finance-flash-<?=$e($flash[0])?>" role="status"><?=$e($flash[1])?></p><?php endif;?>
<section class="card recurring-card">
<div class="recurring-head"><div><h2>Assinaturas e recorrências</h2><p class="muted">Controle cobranças repetidas e receitas recorrentes em um só lugar.</p></div><div class="finance-toolbar-actions"><button class="finance-button" type="button" data-entry-open="income" data-entry-repeat="subscription"<?=$accounts===[]?' disabled title="Cadastre uma conta primeiro"':''?>>+ Receita recorrente</button><button class="finance-button is-primary" type="button" data-entry-open="expense" data-entry-repeat="subscription"<?=$accounts===[]?' disabled title="Cadastre uma conta primeiro"':''?>>+ Assinatura ou despesa</button></div></div>
<nav class="recurring-tabs" aria-label="Situação das recorrências">
<?php foreach(['active'=>'Ativas','paused'=>'Pausadas','canceled'=>'Canceladas'] as $key=>$label):?><a href="<?=$e($base.'?situacao='.$key)?>"<?=$status===$key?' class="is-active" aria-current="page"':''?>><?=$label?> (<?=$counts[$key]?>)</a><?php endforeach;?>
</nav>
<?php if($rows===[]):?><div class="recurring-empty"><strong>Nenhuma recorrência nesta situação</strong><p>Cadastre assinaturas, contas fixas ou receitas que se repetem.</p></div><?php else:?>
<div class="recurring-table-wrap"><table class="recurring-table"><caption class="sr-only">Lista de assinaturas e recorrências</caption><thead><tr><th>Descrição</th><th>Categoria</th><th>Valor</th><th>Frequência</th><th>Próxima cobrança</th><th>Situação</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>
<?php foreach($rows as $row):?><tr><td><?php $brandLogo=SubscriptionBrands::logoUrl((string)$row['name'],(string)($row['provider']??'')); $brandVisual=SubscriptionBrands::visual((string)$row['name'],(string)($row['provider']??'')); ?><span class="recurring-brand" style="--recurring-bg:<?=$e($brandVisual[0])?>;--recurring-fg:<?=$e($brandVisual[1])?>" aria-hidden="true"><?php if($brandLogo!==null):?><img src="<?=$e($brandLogo)?>" width="28" height="28" loading="lazy" decoding="async" alt=""><?php else:?><?=$e($brandVisual[2])?><?php endif;?></span><strong><?=$e($row['name'])?></strong><?php if($row['provider']):?><small><?=$e($row['provider'])?></small><?php endif;?></td><td><span class="recurring-category" style="--category-color:<?=$e($row['category_color']??'#6b7a73')?>"><?=$e($row['category_name']??'Sem categoria')?></span></td><td><?=Finance::money((int)$row['amount_cents'])?></td><td><?=$frequencyLabels[$row['frequency']]?></td><td><?=date('d/m/Y',strtotime($row['next_due_date']))?></td><td><span class="finance-badge <?=$status==='active'?'is-paid':'is-open'?>"><?=$status==='active'?'Ativa':($status==='paused'?'Pausada':'Cancelada')?></span></td><td><details class="recurring-menu"><summary aria-label="Ações para <?=$e($row['name'])?>">•••</summary><div><?php if($status!=='canceled'):?><button type="button" data-entry-edit="<?=$e(json_encode(['id'=>(int)$row['id'],'source'=>'recurring','kind'=>$row['kind'],'description'=>$row['name'],'amount'=>number_format((int)$row['amount_cents']/100,2,',','.'),'due_date'=>$row['next_due_date'],'account_id'=>(int)$row['account_id'],'category_id'=>(int)$row['category_id'],'notes'=>(string)$row['notes'],'provider'=>(string)$row['provider'],'frequency'=>$row['frequency'],'item_type'=>$row['item_type'],'auto_create'=>(bool)$row['auto_create']],JSON_UNESCAPED_UNICODE))?>">Editar</button><?php endif;?><?php if($status==='active'):?><?=$actionForm('pause','Pausar',$row['id'])??''?><?php elseif($status==='paused'):?><?=$actionForm('activate','Reativar',$row['id'])??''?><?php endif;?><?php if($status!=='canceled'):?><?=$actionForm('cancel','Cancelar',$row['id'])??''?><?php endif;?></div></details></td></tr><?php endforeach;?>
</tbody></table></div><?php endif;?>
</section>
<?php
/* Formulários de ação são renderizados sem JavaScript e preservam CSRF. */
$form=['csrf'=>$csrf,'month'=>date('Y-m'),'date'=>date('Y-m-d'),'back'=>'recorrencias'];require dirname(__DIR__).'/components/entry-form.php';
